* BRDS -- Browse the records a KSDS file.
* Copied from 'CONS1'.
MAP BRDS1W SIZE 27x132
  INPUT TRANSID   AT 0,0    LEN 4   PROT COLOR=BLUE
  FIELD           AT 0,5    LEN 21  PROT COLOR=BLUE         "- KSDS Record Browser"
  INPUT TERMID    AT 0,125  LEN 6   PROT COLOR=BLUE
  FIELD           AT 0,120  LEN 5   PROT COLOR=BLUE         "TERM="
  FIELD           AT 2,0    LEN 5   PROT                    "File:"
  INPUT FNAME     AT 2,7    LEN 20  UNDERSCORE COLOR=GREEN
  STOP            AT 2,28
  FIELD           AT 2,29   LEN 10  PROT                    "Start Key:"
  INPUT STARTKEY  AT 2,41   LEN 30  UNDERSCORE COLOR=GREEN
  STOP            AT 2,72
  FIELD           AT 2,73   LEN 16  PROT                    "Field Separator:"
  INPUT FIELDSEP  AT 2,91   LEN 1   UNDERSCORE COLOR=GREEN
  STOP            AT 2,93
  FIELD           AT 2,94   LEN 36  PROT                    "(Blank to treat the record as text.)"
  FIELD           AT 4,0    LEN 4   PROT COLOR=BLUE         "Key:"
  INPUT LASTKEY   AT 4,12   LEN 70  PROT COLOR=GREEN
  FIELD           AT 5,0    LEN 12  PROT COLOR=BLUE         "Record:"
  INPUT PAGES     AT 5,8    LEN 30  PROT COLOR=WHITE
  FIELD MORE_UP   AT 6,2    LEN 10  PROT COLOR=YELLOW
  FIELD MORE_TOP  AT 6,55   LEN 22  PROT COLOR=CYAN
  FIELD ROW1      AT 7,2    LEN 128 PROT COLOR=GREEN
  FIELD ROW2      AT 8,2    LEN 128 PROT COLOR=GREEN
  FIELD ROW3      AT 9,2    LEN 128 PROT COLOR=GREEN
  FIELD ROW4      AT 10,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW5      AT 11,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW6      AT 12,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW7      AT 13,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW8      AT 14,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW9      AT 15,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW10     AT 16,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW11     AT 17,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW12     AT 18,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW13     AT 19,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW14     AT 20,2   LEN 128 PROT COLOR=GREEN
  FIELD ROW15     AT 21,2   LEN 128 PROT COLOR=GREEN
  FIELD MORE_DOWN AT 22,2   LEN 76  PROT COLOR=YELLOW
  FIELD MORE_BOT  AT 22,55  LEN 22  PROT COLOR=CYAN
  FIELD TRUNC1    AT 7,0    LEN 1   PROT COLOR=RED
  FIELD TRUNC2    AT 8,0    LEN 1   PROT COLOR=RED
  FIELD TRUNC3    AT 9,0    LEN 1   PROT COLOR=RED
  FIELD TRUNC4    AT 10,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC5    AT 11,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC6    AT 12,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC7    AT 13,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC8    AT 14,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC9    AT 15,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC10   AT 16,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC11   AT 17,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC12   AT 18,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC13   AT 19,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC14   AT 20,0   LEN 1   PROT COLOR=RED
  FIELD TRUNC15   AT 19,0   LEN 1   PROT COLOR=RED
  INPUT MSG       AT 23,0   LEN 79  PROT BRIGHT COLOR=RED
  FIELD           AT 25,0   LEN 130 PROT COLOR=BLUE         "ENTER=Read   PF1=Help   PF3=Exit   PF5=Reset   PF6=Separator   PF7=Previous   PF8=Next   Scroll: PF9=Up   PF10=Down      PF23=Demo"
  CURSOR          AT FNAME
ENDMAP
